 void Hover(object sender,DragEventArgs e){e.Effect=editor.DragEffect(e,owner);editor.DragScroll(new Point(e.X,e.Y));insertion=e.Effect==DragDropEffects.None?null:PointToClient(new Point(e.X,e.Y)).Y<Height/2?"top":"bottom";Invalidate();}
