 Project RestoreSnapshot(History snapshot){Project p=ProjectIO.FromJson(snapshot.Json);p.SourcePath=snapshot.SwitchDocument?snapshot.SourcePath:Project.SourcePath;if(snapshot.SwitchDocument)filePath=snapshot.FilePath;return p;}
