 void UpdateTimingLabel(){if(timingButton!=null)timingButton.Text="Przerwy: "+Project.StepDelaySeconds.ToString("0.##",System.Globalization.CultureInfo.GetCultureInfo("pl-PL"))+" s";if(timingSeconds!=null){syncingDelay=true;try{decimal value=Math.Round((decimal)Project.StepDelaySeconds,2);if(timingSeconds.Value!=value)timingSeconds.Value=value;}finally{syncingDelay=false;}}}
