 public void ApplyAiProject(Project generated,bool modifyCurrent=true){Project next=ProjectIO.FromJson(ProjectIO.Json(generated));next.SourcePath=modifyCurrent?Project.SourcePath:null;History snapshot=CaptureSnapshot(!modifyCurrent);undo.Push(snapshot);if(undo.Count>80)undo=new Stack<History>(undo.Take(80).Reverse());redo.Clear();if(!modifyCurrent)filePath=null;Preview.Stop();designer.Checked=false;Project=next;Changed();Render();RenderPalette();Preview.Reset(Project);status.Text="AI wstawiło "+ProjectIO.Count(Project.Blocks)+" bloczków. F5: sprawdź działanie • Cofnij: przywróć poprzedni projekt • Kompiluj: zapisz .js";}
 void ImportImage(){using(OpenFileDialog d=new OpenFileDialog{Filter="Obrazy PNG / JPG / BMP / GIF|*.png;*.jpg;*.jpeg;*.bmp;*.gif",Title="Dodaj obraz do projektu .js"}){if(d.ShowDialog(this)!=DialogResult.OK)return;try{byte[] data=File.ReadAllBytes(d.FileName);if(data.Length>5*1024*1024)throw new Exception("Obraz przekracza 5 MB.");using(MemoryStream m=new MemoryStream(data))using(Image image=Image.FromStream(m)){if((long)image.Width*image.Height>16000000)throw new Exception("Obraz ma za dużą rozdzielczość (limit 16 megapikseli).");}if(Project.Assets.Sum(x=>(long)x.Value.Length)+data.Length*4L/3>28000000)throw new Exception("Limit obrazów w projekcie: około 20 MB.");Remember();string id="obraz"+(Project.Assets.Count+1);while(Project.Assets.ContainsKey(id))id+="_";Project.Assets[id]=Convert.ToBase64String(data);Changed();Render();status.Text="Zaimportowano „"+id+"”. Użyj tej nazwy w kostiumie duszka lub elemencie Obraz.";}catch(Exception e){Error(e.Message);}}}
