 void KeysDown(object sender,KeyEventArgs e){if(e.Control&&e.KeyCode==Keys.S){Save(e.Shift);e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.O){Open();e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.N){New();e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.Enter){Export();e.SuppressKeyPress=true;}else if(e.KeyCode==Keys.F5){if(e.Shift)Preview.Stop();else{designer.Checked=false;viewTabs.SelectedIndex=0;CommitTimingInput();var ignored=Preview.Start(Project);}e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.Z&&!(FocusedControl(this) is TextBoxBase)){Undo();e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.Y&&!(FocusedControl(this) is TextBoxBase)){Redo();e.SuppressKeyPress=true;}}
 static Control FocusedControl(ContainerControl c){Control a=c.ActiveControl;while(a is ContainerControl&&((ContainerControl)a).ActiveControl!=null)a=((ContainerControl)a).ActiveControl;return a;}
