 public async Task Snapshot(string path,bool terminal=false){Show();Application.DoEvents();if(terminal){categories.SelectedIndex=Array.IndexOf(Catalog.Groups,"Terminal")+1;foreach(Block block in Project.Blocks)if(!Catalog.All[block.Kind].Event)block.Collapsed=true;RenderPalette();}Render();if(Project.Blocks.Count>0)await Preview.Start(Project);else Preview.Reset(Project);if(terminal){Block firstEvent=Project.Blocks.FirstOrDefault(b=>Catalog.All[b.Kind].Event);if(firstEvent!=null&&Cards.ContainsKey(firstEvent))workspace.AutoScrollPosition=new Point(0,Cards[firstEvent].Top);Highlight(null);}Application.DoEvents();using(Bitmap bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(0,0,Width,Height));bmp.Save(path);}}
 public static string HelpText(){return "EASYJAVA 2\r\n\r\nAI Z OLLAMĄ\r\nKliknij AI • Ollama w górnym pasku. Ollama musi działać (domyślnie http://127.0.0.1:11434). Wybierz model z listy lub wpisz jego nazwę i kliknij Pobierz model. Wpisz po polsku, co ma robić program, i kliknij Wygeneruj. Popraw bieżący projekt wysyła także jego bloczki do wybranego serwera. Obejrzyj propozycję i kliknij Użyj projektu. Wstawienie można cofnąć. F5 uruchamia podgląd, Kompiluj na pulpit zapisuje .js. AI nie uruchamia projektu samo. Model pobiera się osobno; zwykłe bloczki działają bez Ollamy.\r\n\r\nBloczki dodajesz wyłącznie przez przeciąganie i upuszczanie z biblioteki. Samo kliknięcie niczego nie dodaje. Istniejące bloczki przenoś za tytuł lub uchwyt.\r\n\r\nPodczas przeciągania widać bloczek pod kursorem i linię miejsca upuszczenia. Zdarzenia umieszczaj na głównym poziomie. Pętle, warunki i zdarzenia mają miejsce w środku. Upuść tam bloczki. Warunek z alternatywą ma drugą gałąź.\r\n\r\n● w nagłówku włącza / wyłącza bloczek. Wyłączenie pętli lub zdarzenia pomija też jego wnętrze. Funkcje w górnym pasku wyłączają całe kategorie.\r\n\r\nPRZERWY MIĘDZY BLOCZKAMI\r\nNad bloczkami jest pole Przerwa między bloczkami. Wpisz od 0 do 3600 sekund. Zmiana działa od razu, bez przycisku Zastosuj. Przycisk Przerwy u góry otwiera też gotowe wartości.\r\nAby dodać przerwę tylko w jednym miejscu, przeciągnij Sterowanie → Czekaj między dwa polecenia i wpisz liczbę sekund. Link nad skryptami pomaga znaleźć ten bloczek. Wyszukasz go też jako przerwa, pauza lub odstęp. Pierwsze polecenie rusza od razu; kolejne czekają ustawiony czas. 0 wyłącza dodatkową pauzę. Ustawienie zapisuje się w .js i działa też poza edytorem.\r\nPętle i warunki przekazują odstęp do poleceń w środku, bez podwójnych pauz. Nowe zdarzenie startuje od razu. Komentarze i wyłączone bloczki nie wydłużają odstępu. Bloczek Czekaj dodaje własny czas do odstępów. Stop przerywa czekanie.\r\n\r\nPODGLĄD\r\nFlaga lub F5 uruchamia projekt. ■ lub Shift+F5 zatrzymuje wszystkie skrypty. Kliknij scenę przed sterowaniem klawiszami. W podglądzie widać rzeczywiste okna i elementy GUI, duszki oraz wynik działania.\r\n\r\nPROJEKTANT GUI\r\nZaznacz Projektant GUI i przeciągaj elementy okna. Pozycje X i Y zapisują się w bloczkach. W tym trybie zdarzenia i pliki nie działają. Potem kliknij Uruchom podgląd.\r\n\r\nZAPIS I KOMPILACJA\r\nZapisz .js zachowuje jeden plik, który można uruchomić lub otworzyć w EasyJava do dalszej edycji. Kompiluj na pulpit tworzy wyłącznie plik .js. Uruchom go dwuklikiem. Skróty .lnk nie są tworzone. Node.js nie jest wymagany. Kopie zastępowanych plików trafiają do lokalnego folderu EasyJava/Kopie.\r\n\r\nGUI\r\nNajpierw dodaj elementy, nadając im unikalne identyfikatory, np. input1 i button1. Zdarzenie Kiedy kliknięto przycisk z identyfikatorem button1 reaguje na kliknięcie. Odczytaj wartość elementu zapisuje wpisany tekst do zmiennej. Wczytaj przykład Panel GUI.\r\n\r\nDUSZKI\r\nUtwórz duszka lub wybierz już istniejącego. Każdy skrypt ma własnego aktywnego duszka. Nowy projekt jest zawsze pusty. Gotowe przykłady uruchamia się wyłącznie z listy.\r\n\r\nŚrodek sceny to 0,0. Kierunek 0 oznacza prawo, 90 górę. Dostępne są ruch, lot, odbicie, dymki, kostiumy i pisak.\r\n\r\nZMIENNE I OBLICZENIA\r\nW tekście używaj {nazwa}, np. Wynik: {punkty}. Liczby możesz zapisywać z przecinkiem. Pole zaczynające się od = jest wyrażeniem, np. =punkty * 2 + 1.\r\nOperatory: + - * / % ^ == != < > <= >= && || !\r\nFunkcje: sqrt, abs, round, floor, ceil, sin, cos, tan, log, min, max, len. Funkcje używają przecinka jako separatora argumentów; liczby w wyrażeniu zapisuj z kropką.\r\nListy są numerowane od 1.\r\n\r\nOBRAZY\r\nImportuj obraz osadza go w projekcie .js. Identyfikator obrazu można wpisać w bloczku Obraz lub w polu kostiumu duszka.\r\n\r\nTERMINAL: CMD I POWERSHELL\r\nUpuść nowy bloczek, aby włączyć Terminal, lub użyj Funkcji. Przeciągnij bloczek Uruchom polecenie CMD lub PowerShell do skryptu. Wpisz dosłowny kod powłoki, np. echo Witaj lub Write-Output 'Witaj'. Klamry i cudzysłowy w kodzie są zachowane.\r\nPo uruchomieniu pojawia się osobne okno GUI z treścią komendy oraz zakładką Terminal, która pokazuje kolory i animacje ANSI, np. curl parrot.live, oraz zakładkami Wynik (tekst) i Błędy. Wynik napływa na żywo, a okno zostaje po zakończeniu komendy. Zatrzymaj lub zamknięcie aktywnego okna przerywa komendę i ten skrypt.\r\nWynik, błędy i kod wyjścia trafiają też do trzech wskazanych zmiennych. Pole Działanie: Czekaj wstrzymuje kolejne bloczki do zakończenia komendy. W tle pozwala im działać od razu — wybierz to np. przy curl parrot.live, jeśli dalej zapisujesz TXT. Wynik trafia do zmiennych dopiero po zakończeniu komendy. Zatrzymaj i limit czasu w trybie W tle przerywają tylko komendę; globalny Stop kończy wszystkie skrypty i komendy. Pusty folder roboczy oznacza folder projektu .js; niezapisany podgląd używa pulpitu. Limit czasu wynosi od 1 do 3600 sekund; Stop przerywa aktywną komendę. Wynik pokażesz np. tekstem {wynik_komendy}.\r\nTerminal jest domyślnie wyłączony. Komendy działają z uprawnieniami użytkownika i mogą zmieniać pliki i ustawienia. EasyJava nie podnosi uprawnień ani nie zmienia zasad PowerShell. Tryb --smoke pomija ich wykonywanie; pełny --selftest uruchamia osobne komendy testowe.\r\n\r\nPLIKI\r\nNowy bloczek włącza kategorię Pliki; możesz też użyć Funkcji. Podaj np. {pulpit}\\notatka.txt. Sama nazwa notatka.txt zapisuje obok projektu .js. Sama ścieżka folderu nie wystarczy. Użyj Wybierz plik do odczytu / zapisu, a potem odczytuj lub zapisuj tekst. Zapis pyta przed zastąpieniem istniejącego pliku. Pole Tekst obsługuje wiele wierszy. Po zapisie zobaczysz potwierdzenie i ścieżkę w dzienniku. Jeśli przed zapisem jest nieskończona komenda, ustaw w niej Działanie: W tle albo przesuń zapis przed komendę.\r\n\r\nPRZYKŁADY\r\nPanel GUI, licznik kliknięć, sterowanie duszkiem, rysujący robot, gra ze zbieraniem gwiazdy, lista zadań, notatnik oraz CMD i PowerShell z przycisków.\r\n\r\nTo osobny edytor inspirowany Scratchem, rozwijany jako aplikacja Windows. Nie wczytuje projektów .sb3.\r\n";}
